1	/* ===== Dù lượn, đi dạo và lái xe nhiều người: máy trạng thái phiên (không DOM, không three) =====
2	   Một phiên thuộc một loại (kind): 'fly' giành chỗ bay, 'walk' giành chỗ đi dạo, 'drive' giành chỗ lái xe. Ba nhóm 5 slot riêng; peers là nhóm cùng loại với mình
3	   (dùng cho đầy chỗ, chọn người xem, lời mời). Phase 'flying' nghĩa là "đang giữ chỗ" cho mọi loại (đi dạo, lái xe cũng vậy). */
4	import type { Flyer, Kind, ServerMsg } from './protocol';
5	import type { Transport } from './client';
6	import { multiParams } from './params';
7	
8	export type Phase = 'connecting' | 'lobby' | 'flying' | 'watching' | 'solo';
9	export type Notice = '' | 'offline' | 'lost' | 'late' | 'nameBad' | 'released';
10	
11	export class MultiSession {
12	  phase: Phase = 'connecting';
13	  flyers: Flyer[] = [];
14	  walkers: Flyer[] = [];   // người đi dạo (lobby.walkers); máy chủ cũ không gửi
15	  drivers: Flyer[] = [];   // người lái xe (lobby.drivers); máy chủ cũ không gửi
16	  mySlot = -1;
17	  watched = -1;       // slot đang xem (trong nhóm cùng loại), -1 = không ai
18	  invite = false;     // đang xem và còn chỗ trống
19	  notice: Notice = '';
20	  name = '';
21	  onChange: () => void = () => {};
22	  onPos: (f: number[][]) => void = () => {};
23	  onWalkPos: (w: number[][]) => void = () => {};
24	  peersDrive: (d: number[][]) => void = () => {};   // nhóm d của gói pos (mẫu onWalkPos): mỗi phần tử [slot, x, y, z, yaw, v, st, giờ gửi]
25	  private t: Transport | null = null;
26	  private disposed = false;
27	  private first = true; // chưa nhận lobby nào
28	
29	  constructor(private connect: () => Promise<Transport>, private pick: (n: number) => number = n => Math.floor(Math.random() * n), readonly kind: Kind = 'fly') {}
30	
31	  /* Danh sách cùng loại với mình */
32	  get peers(): Flyer[] { return this.kind === 'walk' ? this.walkers : this.kind === 'drive' ? this.drivers : this.flyers; }
33	
34	  /* Số chỗ của nhóm cùng loại */
35	  private get cap(): number { return this.kind === 'walk' ? multiParams.stroll.slots : this.kind === 'drive' ? multiParams.drive.slots : multiParams.slots; }
36	
37	  open(): void {
38	    this.connect().then(t => {
39	      if (this.disposed) { t.close(); return; }
40	      this.t = t;
41	      t.onMessage = m => this.recv(m);
42	      t.onClose = () => this.lost();
43	    }, () => {
44	      if (this.disposed) return;
45	      this.phase = 'solo'; this.notice = 'offline'; this.onChange();
46	    });
47	  }
48	
49	  /* Người lái chỉ xin chỗ sau khi lobby đầu đã có drivers: máy chủ cũ (main trước D-034) coi join kind 'drive' là join bay và cho chiếm một chỗ bay */
50	  join(name: string): void {
51	    this.name = name; this.notice = '';
52	    if (this.kind === 'drive' && this.first) return;
53	    this.t?.send(this.kind === 'fly' ? { t: 'join', name } : { t: 'join', name, kind: this.kind });
54	  }
55	
56	  // Rời chỗ (do rời máy): trả slot, chuyển sang xem, báo 'released' như khi máy chủ thu hồi chỗ
57	  leave(): void {
58	    if (this.phase !== 'flying') return;
59	    this.t?.send({ t: 'leave' });
60	    this.notice = 'released'; this.toWatching();
61	    this.onChange();
62	  }
63	
64	  // ts: giờ gửi (ms, đồng hồ của khách này) để người xem đặt mẫu theo trục giờ người gửi
65	  sendPos(x: number, y: number, z: number, yaw: number, bank: number, ts: number): void {
66	    if (this.phase === 'flying') this.t?.send({ t: 'pos', x, y, z, yaw, bank, ts });
67	  }
68	
69	  // Người đi dạo: pose (0 đứng, 1 đi, 2 chạy, 3 rơi (bản cũ: nhảy), 4 chụp ảnh) thay cho bank
70	  sendWalk(x: number, y: number, z: number, yaw: number, pose: number, ts: number): void {
71	    if (this.phase === 'flying') this.t?.send({ t: 'pos', x, y, z, yaw, pose, ts });
72	  }
73	
74	  // Người lái: v tốc độ có dấu (m/s), st góc lái (rad) thay cho bank / pose; ts giờ gửi (ms, đồng hồ khách này), không truyền thì lấy performance.now()
75	  sendDrive(p: { x: number; y: number; z: number; yaw: number; v: number; st: number; ts?: number }): void {
76	    if (this.phase !== 'flying') return;
77	    const ts = typeof p.ts === 'number' ? p.ts : Math.round(performance.now());
78	    this.t?.send({ t: 'pos', x: p.x, y: p.y, z: p.z, yaw: p.yaw, v: p.v, st: p.st, ts });
79	  }
80	
81	  heartbeat(): void {
82	    if (this.phase === 'flying') this.t?.send({ t: 'hb' });
83	  }
84	
85	  dispose(): void {
86	    this.disposed = true;
87	    this.t?.close(); this.t = null;
88	  }
89	
90	  private toWatching(): void {
91	    this.phase = 'watching'; this.mySlot = -1;
92	    if (this.kind === 'walk') this.walkers = this.walkers.filter(f => f.slot !== this.mySlotWas);
93	    else if (this.kind === 'drive') this.drivers = this.drivers.filter(f => f.slot !== this.mySlotWas);
94	    else this.flyers = this.flyers.filter(f => f.slot !== this.mySlotWas);
95	    this.fixWatched();
96	  }
97	  private mySlotWas = -1;
98	
99	  // Giữ watched nếu người đó còn; không thì chọn ngẫu nhiên người khác (cùng loại)
100	  private fixWatched(): void {
101	    const ids = this.peers.map(f => f.slot);
102	    if (this.phase === 'watching') {
103	      if (!ids.includes(this.watched)) this.watched = ids.length ? ids[this.pick(ids.length)] : -1;
104	      this.invite = ids.length < this.cap;
105	    } else { this.watched = -1; this.invite = false; }
106	  }
107	
108	  private lost(): void {
109	    if (this.disposed) return;
110	    this.phase = 'solo'; this.notice = 'lost';
111	    this.flyers = []; this.walkers = []; this.drivers = []; this.mySlot = -1; this.watched = -1; this.invite = false;
112	    this.t = null; this.onChange();
113	  }
114	
115	  /* Máy chủ cũ (lobby đầu không có walkers / drivers) không biết chỗ đi dạo / lái xe: đóng kết nối, đi / lái một mình như khi không kết nối được */
116	  private offline(): void {
117	    const t = this.t;
118	    this.t = null;
119	    if (t) { t.onClose = () => {}; t.onMessage = () => {}; t.close(); }
120	    this.phase = 'solo'; this.notice = 'offline';
121	    this.flyers = []; this.walkers = []; this.drivers = [];
122	    this.onChange();
123	  }
124	
125	  private recv(m: ServerMsg): void {
126	    if (this.disposed) return;
127	    switch (m.t) {
128	      case 'lobby':
129	        if (this.first && this.kind === 'walk' && !Array.isArray(m.walkers)) { this.first = false; this.offline(); return; }
130	        if (this.first && this.kind === 'drive' && !Array.isArray(m.drivers)) { this.first = false; this.offline(); return; }
131	        this.flyers = m.flyers;
132	        this.walkers = Array.isArray(m.walkers) ? m.walkers : [];
133	        this.drivers = Array.isArray(m.drivers) ? m.drivers : [];
134	        if (this.first) {
135	          this.first = false;
136	          if (this.peers.length >= this.cap) this.phase = 'watching';
137	          else this.phase = 'lobby';
138	        }
139	        // đang giữ chỗ: danh sách chỉ để hiển thị
140	        this.fixWatched();
141	        break;
142	      case 'joined':
143	        this.phase = 'flying'; this.mySlot = m.slot; this.mySlotWas = m.slot; this.notice = '';
144	        this.fixWatched();
145	        break;
146	      case 'rejected':
147	        if (m.why === 'name') this.notice = 'nameBad';
148	        else {
149	          this.notice = 'late';   // giành trước khi đang xem, hoặc ngay ở sảnh (chỗ cuối vừa có người lúc bấm): đều báo lý do
150	          this.phase = 'watching';
151	          this.fixWatched();
152	        }
153	        break;
154	      case 'pos':
155	        this.onPos(m.f);
156	        if (Array.isArray(m.w)) this.onWalkPos(m.w);
157	        if (Array.isArray(m.d)) this.peersDrive(m.d);
158	        return;
159	      case 'released':
160	        if (this.phase === 'flying') { this.notice = 'released'; this.toWatching(); }
161	        break;
162	    }
163	    this.onChange();
164	  }
165	}
