1	/* ===== Dù lượn và đi dạo nhiều người: điều phối phía khách =====
2	   Nối MultiSession (kết nối, phiên) với exRemotes (dù người khác), stAvatars (người đi dạo khác), nhãn tên và danh sách người chơi.
3	   Người bay thấy người đi dạo và ngược lại; mỗi phiên chỉ giữ một loại chỗ (session.kind).
4	   Chỉ mở kết nối khi có người gọi begin(); ?test mà không có multi= thì url() rỗng nên không bao giờ mở WebSocket. */
5	import { scene, camera } from '../../core/renderer';
6	import { CONFIG } from '../../config';
7	import { t, onChange as onLang } from '../../i18n';
8	import { exConnect } from './client';
9	import { MultiSession } from './session';
10	import { exRemotes } from './remote';
11	import { exLabelsUpdate, exLabelsClear } from './labels';
12	import { ExIdle } from './idle';
13	import { stAvatars } from '../stroll/avatars';
14	import type { Kind } from './protocol';
15	import type { GliderState } from '../flight';
16	import type { StState } from '../stroll/motion';
17	
18	const M = CONFIG.explore.multi;
19	let session: MultiSession | null = null;
20	let sentAt = -1e9;
21	let rosterKey = '';
22	let idle: ExIdle | null = null;
23	let idleTimer = 0, beatTimer = 0;   // setInterval kiểm tra rời máy + nhịp sống; chỉ chạy khi đang bay
24	let idleShown = '';                 // chữ đang hiện ở #exMpIdle ('' = ẩn): chỉ ghi DOM khi đổi
25	
26	/* ===== Rời máy: đếm bằng setInterval (tab ẩn vẫn đếm), hết hạn thì trả slot và sang chế độ xem ===== */
27	/* ?idleMs / ?idleWarnMs chỉ đọc khi có ?test (để test rút ngắn) */
28	function idleParams(): [number, number] {
29	  const q = new URLSearchParams(location.search);
30	  if (!q.has('test')) return [M.idleMs, M.idleWarnMs];
31	  const n = (k: string, d: number) => { const v = Number(q.get(k)); return q.has(k) && v > 0 ? v : d; };
32	  return [n('idleMs', M.idleMs), n('idleWarnMs', M.idleWarnMs)];
33	}
34	
35	function idleShow(text: string): void {
36	  const el = document.getElementById('exMpIdle');
37	  if (!el || text === idleShown) return;
38	  /* Lần đầu hiện thì đọc to một lần; các giây sau chỉ đổi chữ, không đọc lại */
39	  el.setAttribute('aria-live', idleShown === '' ? 'polite' : 'off');
40	  idleShown = text;
41	  el.textContent = text;
42	  el.hidden = text === '';
43	}
44	
45	function idleTick(): void {
46	  if (!session || !idle || session.phase !== 'flying') return;
47	  const now = performance.now();
48	  const st = idle.tick(now);
49	  if (st === 'ok') idleShow('');
50	  else if (st === 'warn') idleShow(t('exMpIdle', { s: idle.remaining(now) }));
51	  else { idleShow(''); session.leave(); }   // leave → onChange → idleStop
52	}
53	
54	function idleStart(): void {
55	  if (idleTimer || !session) return;   // đã chạy: không mở hai đồng hồ
56	  const [a, b] = idleParams();
57	  idle = new ExIdle(a, b); idle.reset(performance.now());
58	  idleShown = '';
59	  idleTimer = window.setInterval(idleTick, M.idleTickMs);
60	  beatTimer = window.setInterval(() => session?.heartbeat(), M.heartbeatMs);
61	}
62	
63	function idleStop(): void {
64	  clearInterval(idleTimer); clearInterval(beatTimer);
65	  idleTimer = beatTimer = 0; idle = null;
66	  idleShow('');
67	}
68	
69	/* Danh sách người chơi ở góc màn hình: đầu "Đi dạo n/5 · Bay n/5", rồi nhóm người đi dạo (chấm vuông) và nhóm người bay (chấm tròn),
70	   mỗi người một dòng có chấm màu theo slot; dòng của mình đậm. Dùng textContent */
71	function renderRoster(): void {
72	  const box = document.getElementById('exMpRoster');
73	  if (!box) return;
74	  const flyers = session ? session.flyers : [], walkers = session ? session.walkers : [];
75	  const head = t('stRoster', { w: walkers.length, f: flyers.length });
76	  const kind = session ? session.kind : 'fly', mine = session ? session.mySlot : -1;
77	  const key = walkers.map(f => f.slot + ':' + f.name).join('|') + '#' + flyers.map(f => f.slot + ':' + f.name).join('|') + '#' + kind + mine + '#' + head;
78	  if (key === rosterKey) return;
79	  rosterKey = key;
80	  box.hidden = !session || session.phase === 'solo';
81	  box.textContent = '';
82	  const h = document.createElement('div'); h.className = 'ex-mp-head'; h.textContent = head; box.appendChild(h);
83	  const group = (list: typeof flyers, k: 'fly' | 'walk') => {
84	    for (const f of list) {
85	      const row = document.createElement('div'); row.className = 'ex-mp-row' + (k === 'walk' ? ' walk' : '') + (k === kind && f.slot === mine ? ' me' : '');
86	      const dot = document.createElement('i'); dot.style.background = M.colors[f.slot % M.colors.length];
87	      const nm = document.createElement('span'); nm.textContent = f.name;
88	      row.append(dot, nm); box.appendChild(row);
89	    }
90	  };
91	  group(walkers, 'walk'); group(flyers, 'fly');
92	}
93	
94	/* Người đi dạo hiện cho cả người bay: dựng nhóm nhân vật (lười) lần đầu phòng có người đi dạo; mô hình có xương nạp khi slot đầu tiên hiện */
95	function stEnsureAvatars(): void {
96	  const mesh = stAvatars.build();
97	  if (!mesh.parent) scene.add(mesh);
98	}
99	
100	export const exMulti = {
101	  /* Địa chỉ máy chủ: có ?test thì ?multi= nếu có, không có thì rỗng (không mở mạng); không có ?test thì luôn là địa chỉ cấu hình (người ngoài không đổi được máy chủ qua URL) */
102	  url(): string {
103	    const q = new URLSearchParams(location.search);
104	    if (!q.has('test')) return M.url;
105	    return q.get('multi') ?? '';
106	  },
107	  get session(): MultiSession | null { return session; },
108	  onChange: (() => {}) as () => void,   // móc cho giao diện sảnh (Task 6) và test
109	
110	  /* Mở phiên loại kind ('fly' giành chỗ bay, 'walk' giành chỗ đi dạo); onReady gọi một lần khi có thông tin đầu tiên (sảnh hoặc ngoại tuyến). Trả false nếu không có địa chỉ */
111	  begin(onReady: () => void, kind: Kind = 'fly'): boolean {
112	    const url = exMulti.url();
113	    if (!url || session) return false;
114	    const s = session = new MultiSession(() => exConnect(url, M.connectTimeoutMs), undefined, kind);
115	    let ready = false;
116	    s.onPos = f => exRemotes.onPos(f, performance.now());
117	    s.onWalkPos = w => stAvatars.onPos(w, performance.now());
118	    s.onChange = () => {
119	      exRemotes.sync(s.flyers, s.kind === 'fly' ? s.mySlot : -1);   // slot đi dạo và slot bay là hai nhóm: số slot của mình chỉ loại trừ trong nhóm của mình
120	      if (s.walkers.length || stAvatars.mesh) { stEnsureAvatars(); stAvatars.sync(s.walkers, s.kind === 'walk' ? s.mySlot : -1); }
121	      if (s.phase === 'solo') exLabelsClear();
122	      renderRoster();
123	      if (s.phase === 'flying') idleStart(); else idleStop();
124	      exMulti.onChange();
125	      if (!ready) { ready = true; onReady(); }
126	    };
127	    s.open();
128	    return true;
129	  },
130	
131	  /* Đóng phiên (Quay lại / Esc ở sảnh, hoặc chọn Bay một mình khi có máy chủ): đóng WebSocket, ẩn dù người khác, nhãn, danh sách; begin() mở lại được */
132	  end(): void {
133	    if (!session) return;
134	    session.dispose(); session = null;
135	    exMulti.onChange = () => {};
136	    idleStop(); exRemotes.clear(); stAvatars.clear(); exLabelsClear();
137	    rosterKey = ''; renderRoster();
138	  },
139	
140	  /* Mỗi khung (bay, đi dạo hoặc xem): dù người khác, người đi dạo khác, nhãn; đang bay thì gửi vị trí sendHz lần/s (state = null: không gửi) */
141	  update(_dt: number, nowMs: number, state: GliderState | null): void {
142	    if (!session) return;
143	    exRemotes.update(nowMs);
144	    if (stAvatars.mesh) stAvatars.update(nowMs);   // người đi dạo khác, kể cả khi mình bay dù
145	    exLabelsUpdate(camera, exRemotes, nowMs, stAvatars);
146	    if (state && session.kind === 'fly' && session.phase === 'flying' && nowMs - sentAt >= 1000 / M.sendHz) {
147	      sentAt = nowMs;
148	      const p = state.pos, r = (v: number) => Math.round(v * 10) / 10, a = (v: number) => Math.round(v * 1000) / 1000;
149	      session.sendPos(r(p.x), r(p.y), r(p.z), a(state.yaw), a(state.bank), Math.round(nowMs));
150	    }
151	  },
152	
153	  /* Mỗi khung khi đi dạo có chỗ: gửi vị trí + dáng sendHz lần/s (s = null: không gửi) */
154	  updateWalk(nowMs: number, s: StState | null): void {
155	    if (!session || !s || session.kind !== 'walk' || session.phase !== 'flying' || nowMs - sentAt < 1000 / M.sendHz) return;
156	    sentAt = nowMs;
157	    const r = (v: number) => Math.round(v * 100) / 100, a = (v: number) => Math.round(v * 1000) / 1000;
158	    session.sendWalk(r(s.x), r(s.y), r(s.z), a(s.yaw), s.pose, Math.round(nowMs));
159	  },
160	
161	  /* Người chơi vừa bấm phím điều khiển: đếm lại thời gian rời máy */
162	  activity(): void {
163	    if (!idle) return;
164	    idle.activity(performance.now());
165	    idleShow('');
166	  },
167	
168	  /* Trạng thái dù đang xem (khi hết chỗ, Task 6); null nếu không xem ai */
169	  watchState(): GliderState | null {
170	    return session && session.kind === 'fly' && session.phase === 'watching' ? exRemotes.slotState(session.watched) : null;
171	  },
172	
173	  /* Trạng thái người đi dạo đang xem (hết chỗ đi dạo); null nếu không xem ai */
174	  watchWalker(): { x: number; y: number; z: number; yaw: number; pose: number } | null {
175	    return session && session.kind === 'walk' && session.phase === 'watching' && session.watched >= 0 ? stAvatars.slotState(session.watched) : null;
176	  }
177	};
