1	/* ===== Dù lượn và đi dạo nhiều người: nhãn tên nổi cạnh người chơi khác =====
2	   Một div cho mỗi slot bay và mỗi slot đi dạo trong #exMpLabels. Dù: điểm đặt nhãn thấp hơn dù labelBelow m (tên nằm dưới cánh, không che dù);
3	   người đi dạo: cao hơn chân CONFIG.stroll.labelAbove m (trên đầu). Ẩn khi sau camera hoặc slot chưa hiện; nhân vật của mình không có nhãn.
4	   Chỉ ghi DOM khi chữ đổi (tên + khoảng cách, làm tươi ≤ 5 lần/s) hoặc vị trí lệch quá 1 px. Không cấp phát mỗi khung (D-018). */
5	import * as THREE from 'three';
6	import { CONFIG } from '../../config';
7	import type { exRemotes } from './remote';
8	import type { stAvatars } from '../stroll/avatars';
9	
10	const M = CONFIG.explore.multi, NW = M.stroll.slots;
11	interface Lab { el: HTMLElement; txt: string; x: number; y: number; shown: boolean; tMs: number }
12	let labs: Lab[] | null = null;   // M.slots nhãn dù rồi NW nhãn người đi dạo
13	const _v = new THREE.Vector3();
14	
15	function init(): Lab[] | null {
16	  const box = document.getElementById('exMpLabels');
17	  if (!box) return null;
18	  return Array.from({ length: M.slots + NW }, () => {
19	    const el = document.createElement('div'); el.className = 'ex-mp-label'; el.hidden = true; box.appendChild(el);
20	    return { el, txt: '', x: -1e9, y: -1e9, shown: false, tMs: -1e9 };
21	  });
22	}
23	
24	// Khoảng cách làm tròn: < 1000 m ghi "NNN m", còn lại "N.N km"
25	const dist = (d: number) => d < 1000 ? `${Math.round(d)} m` : `${(d / 1000).toFixed(1)} km`;
26	
27	/* Đặt một nhãn tại điểm (x, y, z) với tên name; trả true nếu hiện */
28	function place(L: Lab, camera: THREE.Camera, x: number, y: number, z: number, name: string, nowMs: number, w: number, h: number): boolean {
29	  _v.set(x, y, z).applyMatrix4(camera.matrixWorldInverse);
30	  if (-_v.z <= 0.1) return false;   // sau camera
31	  _v.applyMatrix4(camera.projectionMatrix);
32	  const px = (_v.x * 0.5 + 0.5) * w, py = (-_v.y * 0.5 + 0.5) * h;
33	  if (px <= -80 || px >= w + 80 || py <= -40 || py >= h + 40) return false;
34	  if (nowMs - L.tMs >= 200) {
35	    L.tMs = nowMs;
36	    const txt = `${name} · ${dist(Math.hypot(x - camera.position.x, y - camera.position.y, z - camera.position.z))}`;
37	    if (txt !== L.txt) { L.txt = txt; L.el.textContent = txt; }
38	  }
39	  if (Math.abs(px - L.x) > 1 || Math.abs(py - L.y) > 1) { L.x = px; L.y = py; L.el.style.transform = `translate(${px.toFixed(0)}px,${py.toFixed(0)}px) translateX(-50%)`; }
40	  return true;
41	}
42	
43	export function exLabelsUpdate(camera: THREE.Camera, remotes: typeof exRemotes, nowMs: number, walkers?: typeof stAvatars): void {
44	  if (!labs && !(labs = init())) return;
45	  const w = window.innerWidth, h = window.innerHeight;
46	  for (let i = 0; i < M.slots; i++) {
47	    const L = labs[i], st = remotes.slotState(i);
48	    const vis = !!st && place(L, camera, st.pos.x, st.pos.y - M.labelBelow, st.pos.z, remotes.name(i), nowMs, w, h);
49	    if (vis !== L.shown) { L.shown = vis; L.el.hidden = !vis; }
50	  }
51	  for (let i = 0; i < NW; i++) {
52	    const L = labs[M.slots + i], st = walkers && i !== walkers.self ? walkers.slotState(i) : null, nm = st ? walkers!.name(i) : null;
53	    const vis = !!st && nm !== null && place(L, camera, st.x, st.y + CONFIG.stroll.labelAbove, st.z, nm, nowMs, w, h);
54	    if (vis !== L.shown) { L.shown = vis; L.el.hidden = !vis; }
55	  }
56	}
57	
58	/* Ẩn hết nhãn (rời phòng) */
59	export function exLabelsClear(): void {
60	  if (!labs) return;
61	  for (const L of labs) { L.shown = false; L.el.hidden = true; L.x = L.y = -1e9; }
62	}
