22	export function saveName(n: string): void { try { localStorage.setItem(NAME_KEY, n); } catch { /* bộ nhớ trình duyệt bị chặn */ } }
23	
24	let listKey = '';
25	let bound = false;
26	let cur: { session: MultiSession; cb: LobbyCallbacks } | null = null;   // sảnh đang mở; null = đã đóng (vào bay, xem, bay một mình, quay lại)
27	
28	/* Đóng sảnh rồi gọi f (một lần) */
29	function finish(f: () => void): void {
30	  if (!cur) return;
31	  cur = null; exMulti.onChange = () => {};
32	  f();
33	}
34	
35	/* Trả hộp thoại về các thẻ: hiện tiêu đề, gắn lại aria-labelledby */
36	function restoreCards(): void {
37	  const root = $('exMpLobby'), box = root.closest('#chooser') as HTMLElement;
38	  root.hidden = true;
