78	  $('exMpOffline').hidden = !offline;
79	  soloBtn.classList.toggle('ex-mp-alt', !offline);   // có máy chủ: nút phụ; ngoại tuyến: nút chính
80	  if (offline) { if (document.activeElement !== soloBtn) soloBtn.focus({ preventScroll: true }); return; }
81	  const ready = ph === 'lobby';
82	  const peers = session.peers;
83	  const free = (walk ? M.stroll.slots : M.slots) - peers.length;
84	  $('exMpSeats').textContent = !ready ? '…' : walk && free <= 0 ? t('stFull') : t(walk ? 'stSeats' : 'exMpSeats', { n: free });
85	  $('exMpNameHint').textContent = t('exMpNameMax', { n: M.nameMax });
86	  const taken = new Set(peers.map(f => f.slot));
87	  $('exMpDots').querySelectorAll<HTMLElement>('i').forEach((d, i) => {
88	    d.classList.toggle('on', taken.has(i));
89	    d.style.background = taken.has(i) ? M.colors[i % M.colors.length] : '';
90	  });
91	  const key = session.kind + '#' + peers.map(f => f.slot + ':' + f.name).join('|');
92	  if (key !== listKey) {
93	    listKey = key;
94	    const list = $('exMpList'); list.textContent = '';
95	    for (const f of peers) {
96	      const row = document.createElement('div'); row.className = 'ex-mp-row';
97	      const dot = document.createElement('i'); dot.style.background = M.colors[f.slot % M.colors.length];
98	      const nm = document.createElement('span'); nm.textContent = f.name; nm.dir = 'auto';
99	      row.append(dot, nm); list.appendChild(row);
100	    }
101	  }
102	  $('exMpNameBad').hidden = session.notice !== 'nameBad';
103	  fly.disabled = !ready || exSanitizeName(input.value) === null;
104	}
105	
106	function go(): void {
107	  if (!cur) return;
108	  const name = exSanitizeName($<HTMLInputElement>('exMpNameIn').value);
109	  if (name === null || cur.session.phase !== 'lobby') return;
110	  saveName(name);
111	  cur.session.join(name);
112	}
113	
114	/* Gắn trình nghe một lần */
115	function bind(): void {
116	  if (bound) return;
117	  bound = true;
118	  const root = $('exMpLobby'), box = root.closest('#chooser') as HTMLElement, input = $<HTMLInputElement>('exMpNameIn');
119	  input.addEventListener('input', () => {
120	    if (!cur) return;
121	    $('exMpNameBad').hidden = true;
122	    const ok = exSanitizeName(input.value);
123	    if (ok !== null) saveName(ok);   // nhớ ngay khi hợp lệ, tải lại trang vẫn còn
124	    $<HTMLButtonElement>('exMpFly').disabled = cur.session.phase !== 'lobby' || ok === null;
125	  });
126	  input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); go(); } });
127	  $('exMpFly').addEventListener('click', go);
128	  $('exMpSolo').addEventListener('click', solo);
129	  $('exMpBack').addEventListener('click', back);
130	  box.addEventListener('keydown', (e) => { if (e.key === 'Escape' && cur) { e.preventDefault(); back(); } });
131	  onLang(() => render());
132	}
133	
134	/* Hiện bước riêng thay cho các thẻ và gắn nó vào phiên; trả ngay (phiên đang ở pha 'connecting') */
135	export function exShowLobby(session: MultiSession, cb: LobbyCallbacks): void {
136	  bind();
137	  const root = $('exMpLobby'), box = root.closest('#chooser') as HTMLElement, input = $<HTMLInputElement>('exMpNameIn');
138	  box.querySelector<HTMLElement>('.ex-cards')!.hidden = true;
139	  $('exTitle').hidden = true; $('exMpLostNote').hidden = true;
140	  box.setAttribute('aria-labelledby', 'exMpSky');
141	  root.hidden = false;
142	  if (!input.value) input.value = loadName();
143	  listKey = '';
