1	/* ============================ Lái xe: điều phối chế độ (lái một mình, máy tính) ============================
2	   Nối mạng đường (net / roadData / solids / sceneSolids), chuyển động + va chạm (motion / collide), hình xe (car / cars),
3	   camera sau xe (camera) với vòng animate, phím, chuột, cảm ứng (touch), HUD (hud: đồng hồ, bản đồ nhỏ, gợi ý), tiếng mô tơ / còi (sound). Mẫu: explore/stroll/index.ts.
4	   `?explore=drive` vào thẳng, lái một mình; thẻ "Ô tô" ở màn chọn cũng lái một mình (sảnh nhiều người: Task 10–11).
5	   Esc và nút Thoát dùng explore.exit() (tải lại trang, D-020); trước đó drive.stop() trả lại các thứ đã đổi.
6	   - Mạng đường dựng MỘT lần ở lần đầu vào chế độ và giữ lại: ô tĩnh + vật cản tĩnh + nhà / chân đế thu từ cảnh (drCollectRuntime chỉ push,
7	     gọi hai lần sẽ nhân đôi vật cản). Chỉ đọc cảnh, sau mọi rand().
8	   - Barie Cầu sông Hàn: cổng DR_GATE_SWING của ô nhịp quay đóng khi cầu rời CLOSED (mỗi khung); không tự quay, không tăng tốc quay (như đi dạo).
9	     Xe đang chạm nhịp quay lúc đó được sơ tán ra ngoài barie gần nhất (motion.ts drEvacStep), gói trong thời gian còn lại trước khi nhịp xoay
10	     (drSwingBudget: coi như nhịp không phải chờ xe tự động rời nhịp, tức thời gian ngắn nhất).
11	   - Xe tự động: mỗi khung lấy hộp các xe đang hiện trong bán kính CONFIG.drive.ai.radius (common/trafficQuery.ts trNearby, mảng tái dùng);
12	     người chơi lao vào thì bị chặn, xe tự động chạy tới thì đi xuyên (collide.ts drMove).
13	   - Ban đêm Cầu Rồng tự phun như khi đi dạo (exNightStep, swing = false).
14	   - Hầm: driveView.far = CONFIG.drive.tunnelFar khi đang lái để mặt đường hầm hiện ở nút giao với hai đường dọc mới; thoát trả 1.
15	   - Xe của mình là xe slot 0 của drCars (màu slot 0 khi lái một mình); xe và bánh chỉ vào cảnh khi vào chế độ (góc nhìn cũ không thêm lệnh vẽ).
16	   - Phím theo e.code (keys.ts), chỉ ghi khi đang lái, bỏ qua ô nhập và tổ hợp Ctrl / Meta / Alt; blur, ẩn tab, focus vào ô nhập thì nhả hết.
17	   - Cảm ứng (touch.ts, #drHud): đọc SAU phím và gộp (giá trị có độ lớn lớn hơn), không xóa phím trên máy lai; reset() cùng chỗ nhả phím. Phím H: còi.
18	   Mỗi khung không cấp phát (D-018). */
19	import type * as THREE from 'three';
20	import { scene, camera, controls, canvas, renderer } from '../../core/renderer';
21	import { composer, onResize } from '../../core/postprocessing';
22	import { cam } from '../../views/state';
23	import { CONFIG } from '../../config';
24	import { driveView } from '../../environment/driveRoads';
25	import { drMakeNet, drSetGate, type DrNet } from './net';
26	import { drBuildPads, DR_GATE_SWING } from './roadData';
27	import { drBuildSolids } from './solids';
28	import { drCollectRuntime, drSceneStats } from './sceneSolids';
29	import { drCreate, drStep, drEvacStep, type DrState, type DrInput } from './motion';
30	import { trNearby } from '../../common/trafficQuery';
31	import type { DrBox } from './collide';
32	import { drCarLoad, drCarSetWarm } from './car';
33	import { drCars } from './cars';
34	import { drCamPlace, drCamDrag, type DrCam } from './camera';
35	import { drInputFromKeys, drBindDrop, DR_KEYS } from './keys';
36	import { drHudShow, drHudHide, drHudUpdate, type DrMapDot } from './hud';
37	import { drTouchBind } from './touch';
38	import { drSound } from './sound';
39	import { exNightStep } from '../nightShows';
40	import type { SwingController } from '../../bridges/song-han/SwingController';
41	
42	const DR_SOLO_SLOT = -1;     // drCreate / drSpawnPose: lái một mình xuất phát ở giữa các chỗ của slot
43	const DR_SELF = 0;           // slot xe của mình trong drCars khi lái một mình (màu slot 0)
44	
45	/* Làm nóng shader của xe (D-018), như stroll/index.ts stRigSetWarm: hai biến thể (vẽ thẳng ra canvas ban ngày, vào render target của composer ban đêm),
46	   đèn / sương / bóng lấy từ cảnh chính, camera chính (đèn lọc theo lớp của nó). Nhóm làm nóng do car.ts dựng, không thêm vào scene */
47	drCarSetWarm(async (o: THREE.Object3D) => {
48	  const rt = renderer.getRenderTarget();
49	  renderer.setRenderTarget(null);
50	  const a = renderer.compileAsync(o, camera, scene);
51	  renderer.setRenderTarget(rt);
52	  await a;
53	  renderer.setRenderTarget(composer.readBuffer);
54	  const b = renderer.compileAsync(o, camera, scene);
55	  renderer.setRenderTarget(rt);
56	  await b;
57	});
58	
59	let net: DrNet | null = null;
60	let state: DrState | null = null;
61	let ctrl: SwingController | null = null;
62	const drKeys = new Set<string>();  // e.code đang giữ
63	const camS: DrCam = { yaw: 0, pitch: 0, idle: 0 };
64	const _inp: DrInput = { gas: 0, brake: 0, steer: 0, hand: false };   // đầu vào tái dùng mỗi khung
65	const NO_OTHERS: DrMapDot[] = [];  // xe người khác trên bản đồ nhỏ: Task 11 truyền; hiện không có
66	let touch: ReturnType<typeof drTouchBind> | null = null;   // điều khiển cảm ứng (setupDrive dựng)
67	const boxes: DrBox[] = [];         // hộp xe tự động gần xe, tái dùng mỗi khung (trNearby chỉ thêm phần tử khi phải nới)
68	let saved: { fov: number; explore: boolean } | null = null;   // thứ start() đổi, stop() trả lại: fov camera, lớp body 'explore' đã có từ trước chưa
69	
70	const active = () => cam.mode === 'car' && state !== null;
71	const isField = (t: EventTarget | null) => !!t && /^(SELECT|INPUT|TEXTAREA)$/.test((t as HTMLElement).tagName || '');
72	
73	/* Mạng đường dựng lần đầu vào chế độ, giữ lại cho các lần sau; cổng nhịp quay theo cầu hiện tại */
74	function drEnsureNet(): DrNet {
75	  if (!net) {
76	    const n = drMakeNet(drBuildPads(), drBuildSolids());
77	    drCollectRuntime(n, (scene.getObjectByName('tp-houses') as THREE.InstancedMesh) || null);   // một lần cho mỗi net (chỉ push)
78	    net = n;                                                         // gán sau khi thu xong: thu lỗi thì lần vào sau thu lại từ đầu
79	  }
80	  if (ctrl) drSetGate(net, DR_GATE_SWING, ctrl.state !== 'CLOSED');
81	  return net;
82	}
83	
84	/* Giây (thời gian thật) còn lại tới lúc nhịp quay bắt đầu xoay (ROTATING_OPEN), giả sử nhịp không phải chờ xe tự động rời nhịp
85	   (spanClear đúng ngay: thời gian ngắn nhất); 0 khi nhịp đã / đang xoay hoặc cầu đóng */
86	function drSwingBudget(c: SwingController): number {
87	  const T = c.cfg.timing, sp = c.speed > 0 ? c.speed : 1;
88	  if (c.state === 'STOP_TRAFFIC') return Math.max(0, T.amber + T.barrier - c.t + T.unlock) / sp;
89	  if (c.state === 'UNLOCK') return Math.max(0, T.unlock - c.t) / sp;
90	  return 0;
91	}
92	
93	/* Một bước: cổng nhịp quay, sơ tán / chuyển động, hình xe, camera, hiệu ứng đêm */
94	function advance(dt: number, inp: DrInput): void {
95	  if (ctrl) drSetGate(net!, DR_GATE_SWING, ctrl.state !== 'CLOSED');
96	  const s = state!;
97	  if (!drEvacStep(s, net!, dt, ctrl ? drSwingBudget(ctrl) : undefined)) drStep(s, inp, net!, boxes, trNearby(s.x, s.z, CONFIG.drive.ai.radius, boxes), dt);
98	  drCars.place(DR_SELF, state!);
99	  drCamPlace(camera, state!, camS, net!, dt);
100	  controls.target.set(state!.x, state!.y, state!.z);   // tâm vùng bóng đổ (main.ts shadowCenter) theo xe
101	  drHudUpdate(state!, NO_OTHERS); drSound.update(state!.v);
102	  exNightStep(dt, false);
103	}
104	
105	/* Xe đứng yên ở (x, z) hướng yaw, trạng thái mới từ drCreate (xóa trạng thái cọ tường); y bỏ trống thì lấy mặt đường cao nhất tại đó.
106	   Dùng cho test (__app.drive) và đặt lại vị trí */
107	function drPlaceAt(x: number, z: number, yaw: number, y?: number): void {
108	  if (!net) return;
109	  const s = drCreate(net, DR_SOLO_SLOT);
110	  let gy = -Infinity;
111	  for (const p of net.pads) {
112	    if (x < p.x0 || x > p.x1 || z < p.z0 || z > p.z1 || (p.gate !== undefined && net.closed.has(p.gate))) continue;
113	    gy = Math.max(gy, p.y(x, z));
114	  }
115	  s.x = x; s.z = z; s.yaw = yaw; s.y = y ?? (Number.isFinite(gy) ? gy : CONFIG.roadY);
116	  state = s;
117	  camS.yaw = 0; camS.pitch = 0; camS.idle = 0;
118	  drCars.place(DR_SELF, s);
119	  drCamPlace(camera, s, camS, net, 0, true);
120	  controls.target.set(s.x, s.y, s.z);
121	}
122	
123	export const drive = {
124	  active,
125	  get state(): DrState | null { return state; },
