1	/* ===== Dù lượn và đi dạo nhiều người: bước chọn slot và nhập tên (trong hộp thoại #chooser) =====
2	   Hiện sau khi bấm thẻ Dù lượn (hoặc Đi dạo) lúc có máy chủ: 5 chấm + "Còn N trên 5 chỗ", tên những người cùng loại (session.peers), ô tên, nút Bay ngay / Đi dạo ngay.
3	   Chữ chọn theo session.kind (khóa exMp* cho dù lượn, st* cho đi dạo); tên nhớ dùng chung cho hai loại.
4	   Cập nhật trực tiếp theo MultiSession; tên người khác chỉ ghi bằng textContent. Tên của mình nhớ ở localStorage.
5	   Pha lobby: cho nhập tên và giành chỗ. Pha solo (không kết nối được): báo ngoại tuyến. Nút Bay một mình hiện ở cả hai pha (đóng phiên rồi bay một mình).
6	   Pha flying: gọi onFly. Pha watching (hết chỗ): gọi onWatch (chế độ xem do Task 7 làm).
7	   Nút Quay lại hoặc Esc: đóng phiên (đóng WebSocket), trả lại các thẻ, tiêu đề và aria-labelledby, gọi onBack để chọn lại.
8	   Trình nghe gắn một lần cho cả trang và đọc sảnh đang mở (cur), nên vào sảnh nhiều lần không nhân đôi. */
9	import { CONFIG } from '../../config';
10	import { t, onChange as onLang } from '../../i18n';
11	import { exMulti } from './index';
12	import { exSanitizeName } from './protocol';
13	import type { MultiSession } from './session';
14	
15	export interface LobbyCallbacks { onFly: () => void; onWatch: () => void; onSolo: () => void; onBack: () => void }
16	
17	const M = CONFIG.explore.multi;
18	const NAME_KEY = 'exMpName';
19	const $ = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;
20	
21	export function loadName(): string { try { return localStorage.getItem(NAME_KEY) || ''; } catch { return ''; } }
22	export function saveName(n: string): void { try { localStorage.setItem(NAME_KEY, n); } catch { /* bộ nhớ trình duyệt bị chặn */ } }
23	
24	let listKey = '';
25	let bound = false;
26	let cur: { session: MultiSession; cb: LobbyCallbacks } | null = null;   // sảnh đang mở; null = đã đóng (vào bay, xem, bay một mình, quay lại)
27	
28	/* Đóng sảnh rồi gọi f (một lần) */
29	function finish(f: () => void): void {
30	  if (!cur) return;
31	  cur = null; exMulti.onChange = () => {};
32	  f();
33	}
34	
35	/* Trả hộp thoại về các thẻ: hiện tiêu đề, gắn lại aria-labelledby */
36	function restoreCards(): void {
37	  const root = $('exMpLobby'), box = root.closest('#chooser') as HTMLElement;
38	  root.hidden = true;
39	  box.querySelector<HTMLElement>('.ex-cards')!.hidden = false;
40	  $('exTitle').hidden = false;
41	  box.setAttribute('aria-labelledby', 'exTitle');
42	}
43	
44	/* Quay lại / Esc: đóng phiên và về các thẻ */
45	function back(): void {
46	  const c = cur; if (!c) return;
47	  finish(() => { exMulti.end(); restoreCards(); c.cb.onBack(); });
48	}
49	
50	/* Bay một mình (có hay không có máy chủ): đóng phiên để không gửi/nhận gì */
51	function solo(): void {
52	  const c = cur; if (!c) return;
53	  finish(() => { exMulti.end(); c.cb.onSolo(); });
54	}
55	
56	/* Ghi chữ theo khóa và nhớ khóa ở data-i18n (đổi ngôn ngữ thì i18n dịch lại đúng khóa của loại sảnh đang mở) */
57	function setKey(id: string, key: string): void {
58	  const el = $(id);
59	  if (el.dataset.i18n !== key) el.dataset.i18n = key;
60	  const v = t(key);
61	  if (el.textContent !== v) el.textContent = v;
62	}
63	
64	function render(): void {
65	  if (!cur) return;
66	  const session = cur.session, cb = cur.cb, walk = session.kind === 'walk';
67	  const fly = $<HTMLButtonElement>('exMpFly'), soloBtn = $<HTMLButtonElement>('exMpSolo'), input = $<HTMLInputElement>('exMpNameIn');
68	  const ph = session.phase;
69	  if (ph === 'flying') { finish(cb.onFly); return; }
70	  if (ph === 'watching') { finish(cb.onWatch); return; }
71	  /* Chữ theo loại sảnh: bầu trời (dù lượn) hoặc sông Hàn (đi dạo) */
72	  setKey('exMpSky', walk ? 'stSky' : 'exMpSky');
73	  setKey('exMpFly', walk ? 'stGo' : 'exMpFly');
74	  setKey('exMpSolo', walk ? 'stSolo' : 'exMpSolo');
75	  setKey('exMpOffline', walk ? 'stOffline' : 'exMpOffline');
76	  const offline = ph === 'solo';
77	  $('exMpOnline').hidden = offline;
78	  $('exMpOffline').hidden = !offline;
79	  soloBtn.classList.toggle('ex-mp-alt', !offline);   // có máy chủ: nút phụ; ngoại tuyến: nút chính
80	  if (offline) { if (document.activeElement !== soloBtn) soloBtn.focus({ preventScroll: true }); return; }
81	  const ready = ph === 'lobby';
82	  const peers = session.peers;
83	  const free = (walk ? M.stroll.slots : M.slots) - peers.length;
84	  $('exMpSeats').textContent = !ready ? '…' : walk && free <= 0 ? t('stFull') : t(walk ? 'stSeats' : 'exMpSeats', { n: free });
85	  $('exMpNameHint').textContent = t('exMpNameMax', { n: M.nameMax });
86	  const taken = new Set(peers.map(f => f.slot));
87	  $('exMpDots').querySelectorAll<HTMLElement>('i').forEach((d, i) => {
88	    d.classList.toggle('on', taken.has(i));
89	    d.style.background = taken.has(i) ? M.colors[i % M.colors.length] : '';
90	  });
91	  const key = session.kind + '#' + peers.map(f => f.slot + ':' + f.name).join('|');
92	  if (key !== listKey) {
93	    listKey = key;
94	    const list = $('exMpList'); list.textContent = '';
95	    for (const f of peers) {
96	      const row = document.createElement('div'); row.className = 'ex-mp-row';
97	      const dot = document.createElement('i'); dot.style.background = M.colors[f.slot % M.colors.length];
98	      const nm = document.createElement('span'); nm.textContent = f.name; nm.dir = 'auto';
99	      row.append(dot, nm); list.appendChild(row);
100	    }
101	  }
102	  $('exMpNameBad').hidden = session.notice !== 'nameBad';
103	  fly.disabled = !ready || exSanitizeName(input.value) === null;
104	}
105	
106	function go(): void {
107	  if (!cur) return;
108	  const name = exSanitizeName($<HTMLInputElement>('exMpNameIn').value);
109	  if (name === null || cur.session.phase !== 'lobby') return;
110	  saveName(name);
111	  cur.session.join(name);
112	}
113	
114	/* Gắn trình nghe một lần */
115	function bind(): void {
116	  if (bound) return;
117	  bound = true;
118	  const root = $('exMpLobby'), box = root.closest('#chooser') as HTMLElement, input = $<HTMLInputElement>('exMpNameIn');
119	  input.addEventListener('input', () => {
120	    if (!cur) return;
121	    $('exMpNameBad').hidden = true;
122	    const ok = exSanitizeName(input.value);
123	    if (ok !== null) saveName(ok);   // nhớ ngay khi hợp lệ, tải lại trang vẫn còn
124	    $<HTMLButtonElement>('exMpFly').disabled = cur.session.phase !== 'lobby' || ok === null;
125	  });
126	  input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); go(); } });
127	  $('exMpFly').addEventListener('click', go);
128	  $('exMpSolo').addEventListener('click', solo);
129	  $('exMpBack').addEventListener('click', back);
130	  box.addEventListener('keydown', (e) => { if (e.key === 'Escape' && cur) { e.preventDefault(); back(); } });
131	  onLang(() => render());
132	}
133	
134	/* Hiện bước riêng thay cho các thẻ và gắn nó vào phiên; trả ngay (phiên đang ở pha 'connecting') */
135	export function exShowLobby(session: MultiSession, cb: LobbyCallbacks): void {
136	  bind();
137	  const root = $('exMpLobby'), box = root.closest('#chooser') as HTMLElement, input = $<HTMLInputElement>('exMpNameIn');
138	  box.querySelector<HTMLElement>('.ex-cards')!.hidden = true;
139	  $('exTitle').hidden = true; $('exMpLostNote').hidden = true;
140	  box.setAttribute('aria-labelledby', 'exMpSky');
141	  root.hidden = false;
142	  if (!input.value) input.value = loadName();
143	  listKey = '';
144	  cur = { session, cb };
145	  exMulti.onChange = render;
146	  render();
147	  input.focus({ preventScroll: true });
148	}
