1	/* ===== Dù lượn và đi dạo nhiều người: giao diện chế độ xem và các thông báo =====
2	   Chữ theo session.kind: khóa exMp* (dù lượn) hoặc st* (đi dạo); tên người đang xem lấy từ exRemotes hoặc stAvatars.
3	   #exMpWatch "Đang xem: tên", #exMpInvite (lời mời khi còn chỗ: ô tên nếu chưa có tên hợp lệ + nút vào bay), #exMpNotice (late / released / lost).
4	   late tự ẩn sau lateMs, released (khi xem) và lost (khi bay) tự ẩn sau noticeMs; nameBad giữ tới khi gõ tên khác.
5	   Không điều khiển camera hay phiên: explore/index.ts gọi exWatchShow / exWatchRender / exWatchHide và tự xử lý chuyển pha.
6	   Mọi tên người khác chỉ ghi bằng textContent, bọc trong cặp cô lập hướng chữ để tên RTL không làm lệch câu. */
7	import { CONFIG } from '../../config';
8	import { t, onChange as onLang } from '../../i18n';
9	import { exSanitizeName } from './protocol';
10	import { exRemotes } from './remote';
11	import { stAvatars } from '../stroll/avatars';
12	import { loadName, saveName } from './lobby';
13	import type { MultiSession } from './session';
14	
15	const $ = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;
16	
17	let session: MultiSession | null = null;
18	let bound = false;
19	let pending = false;       // đã bấm vào bay, chờ máy chủ trả lời: nút khóa để không gửi hai lần
20	let pendingTimer = 0;
21	let lateUntil = 0;         // mốc (ms) hết hạn hiện exMpLate
22	let lateTimer = 0;
23	let relUntil = 0;          // mốc (ms) hết hạn hiện exMpReleased; 0 = chưa hiện trong lần xem này
24	let relTimer = 0;
25	let flyKey = '';           // thông báo khi bay đã hiện (không hiện lại sau khi tự ẩn)
26	let flyTimer = 0;
27	let rejected: string | null = null;   // tên máy chủ vừa từ chối: không dùng lại, không nhớ
28	let noticeKey = '';        // khóa đang hiện ở #exMpNotice ('' = ẩn)
29	
30	/* Tên hợp lệ đã biết: tên đã dùng trong phiên, hoặc tên nhớ ở sảnh; bỏ tên máy chủ đã từ chối */
31	const okName = (n: string): string | null => { const v = exSanitizeName(n); return v !== null && v !== rejected ? v : null; };
32	const knownName = (): string | null => (session && okName(session.name)) || okName(loadName());
33	
34	/* Ghi/ẩn #exMpNotice (dùng cả khi đang bay: mất kết nối) */
35	export function exWatchNotice(key: string): void {
36	  noticeKey = key;
37	  const el = $('exMpNotice');
38	  el.textContent = key ? t(key) : '';
39	  el.hidden = !key;
40	}
41	
42	function unlock(): void { pending = false; clearTimeout(pendingTimer); }
43	
44	/* Hiện exMpLate thêm lateMs từ bây giờ */
45	function armLate(): void {
46	  lateUntil = performance.now() + CONFIG.explore.multi.lateMs;
47	  clearTimeout(lateTimer); lateTimer = window.setTimeout(exWatchRender, CONFIG.explore.multi.lateMs + 50);
48	}
49	
50	function accept(): void {
51	  if (!session || session.phase !== 'watching' || pending) return;
52	  const input = $<HTMLInputElement>('exMpInviteName');
53	  const name = knownName() ?? exSanitizeName(input.value);
54	  if (name === null) return;
55	  pending = true; clearTimeout(pendingTimer);
56	  pendingTimer = window.setTimeout(() => { pending = false; exWatchRender(); }, CONFIG.explore.multi.pendingMs);
57	  session.join(name);   // join xóa notice cũ trước khi vẽ lại, nếu không nameBad cũ sẽ mở khóa nút ngay
58	  exWatchRender();
59	}
60	
61	/* Lời mời: ghi chữ theo loại và nhớ khóa ở data-i18n để đổi ngôn ngữ dịch đúng */
62	function inviteKeys(walk: boolean): void {
63	  for (const [id, fly, st] of [['exMpInviteText', 'exMpInvite', 'stInvite'], ['exMpInviteFly', 'exMpInviteFly', 'stInviteGo']]) {
64	    const el = $(id), key = walk ? st : fly;
65	    if (el.dataset.i18n !== key) { el.dataset.i18n = key; el.textContent = t(key); }
66	  }
67	}
68	
69	export function exWatchRender(): void {
70	  const s = session;
71	  if (!s || s.phase !== 'watching') return;
72	  /* Dòng "Đang xem" */
73	  const walk = s.kind === 'walk';
74	  const nm = s.watched >= 0 ? (walk ? stAvatars.name(s.watched) : exRemotes.name(s.watched)) : null;
75	  const w = $('exMpWatch');
76	  w.hidden = nm === null;
77	  w.textContent = nm === null ? '' : t(walk ? 'stWatch' : 'exMpWatching', { name: '\u2068' + nm + '\u2069' });
78	  /* Thông báo từ phiên: nút đã có trả lời thì mở khóa */
79	  if (pending && (s.notice === 'late' || s.notice === 'nameBad')) {
80	    unlock();
81	    if (s.notice === 'late') armLate();
82	  }
83	  if (s.notice === 'nameBad' && s.name !== rejected) {   // tên bị từ chối: quên tên đó (cả bản đã nhớ), hiện lại ô nhập để gõ tên khác
84	    rejected = s.name;
85	    if (exSanitizeName(loadName()) === rejected) saveName('');
86	    $<HTMLInputElement>('exMpInviteName').value = '';
87	  }
88	  let key = '';
89	  if (s.notice === 'late') key = performance.now() < lateUntil ? (walk ? 'stLate' : 'exMpLate') : '';
90	  else if (s.notice === 'released') {
91	    const now = performance.now();
92	    if (!relUntil) { relUntil = now + CONFIG.explore.multi.noticeMs; clearTimeout(relTimer); relTimer = window.setTimeout(exWatchRender, CONFIG.explore.multi.noticeMs + 50); }
93	    key = now < relUntil ? (walk ? 'stReleased' : 'exMpReleased') : '';
94	  }
95	  else if (s.notice === 'nameBad') key = 'exMpNameBad';
96	  exWatchNotice(key);
97	  /* Lời mời */
98	  const inv = $('exMpInvite'), input = $<HTMLInputElement>('exMpInviteName'), btn = $<HTMLButtonElement>('exMpInviteFly');
99	  inv.hidden = !s.invite;
100	  inviteKeys(walk);
101	  const needName = knownName() === null;
102	  input.hidden = !needName;
103	  btn.disabled = pending || (needName && exSanitizeName(input.value) === null);
104	}
105	
106	/* Bắt đầu hiện giao diện xem cho phiên s */
107	export function exWatchShow(s: MultiSession): void {
108	  session = s; unlock(); lateUntil = 0; relUntil = 0; rejected = null;
109	  if (s.notice === 'late') armLate();   // bị giành chỗ ngay ở sảnh: vào xem kèm lý do
110	  if (!bound) {
111	    bound = true;
112	    $('exMpInviteFly').addEventListener('click', accept);
113	    const input = $<HTMLInputElement>('exMpInviteName');
114	    input.addEventListener('input', exWatchRender);
115	    input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); accept(); } });   // Esc để lọt lên trình nghe chung (thoát)
116	    onLang(() => { if (session) { exWatchRender(); if (noticeKey && session.phase !== 'watching') exWatchNotice(noticeKey); } });
117	  }
118	  exWatchRender();
119	}
120	
121	/* Gỡ giao diện xem (vào bay, hoặc thoát) */
122	export function exWatchHide(): void {
123	  if (session && session.phase === 'flying') { const n = exSanitizeName(session.name); if (n !== null) saveName(n); }   // máy chủ đã nhận tên: bấy giờ mới nhớ
124	  session = null; unlock(); clearTimeout(lateTimer); clearTimeout(relTimer);
125	  $('exMpWatch').hidden = true; $('exMpInvite').hidden = true;
126	  exWatchNotice('');
127	}
128	
129	/* Khi đang bay: hiện một thông báo (mất kết nối) một lần, tự ẩn sau noticeMs; đổi ngôn ngữ thì dịch lại */
130	export function exFlyNotice(s: MultiSession, key: string): void {
131	  session = s;   // để onLang dịch lại
132	  if (key === flyKey) return;
133	  flyKey = key;
134	  exWatchNotice(key);
135	  clearTimeout(flyTimer);
136	  if (key) flyTimer = window.setTimeout(() => { if (noticeKey === key) exWatchNotice(''); }, CONFIG.explore.multi.noticeMs);
137	}
138

1	/* ============================ Lái xe: điều phối chế độ (lái một mình, máy tính) ============================
2	   Nối mạng đường (net / roadData / solids / sceneSolids), chuyển động + va chạm (motion / collide), hình xe (car / cars),
3	   camera sau xe (camera) với vòng animate, phím, chuột, cảm ứng (touch), HUD (hud: đồng hồ, bản đồ nhỏ, gợi ý), tiếng mô tơ / còi (sound). Mẫu: explore/stroll/index.ts.
4	   `?explore=drive` vào thẳng, lái một mình; thẻ "Ô tô" ở màn chọn cũng lái một mình (sảnh nhiều người: Task 10–11).
5	   Esc và nút Thoát dùng explore.exit() (tải lại trang, D-020); trước đó drive.stop() trả lại các thứ đã đổi.
6	   - Mạng đường dựng MỘT lần ở lần đầu vào chế độ và giữ lại: ô tĩnh + vật cản tĩnh + nhà / chân đế thu từ cảnh (drCollectRuntime chỉ push,
7	     gọi hai lần sẽ nhân đôi vật cản). Chỉ đọc cảnh, sau mọi rand().
