45	/* Làm nóng shader của xe (D-018), như stroll/index.ts stRigSetWarm: hai biến thể (vẽ thẳng ra canvas ban ngày, vào render target của composer ban đêm),
46	   đèn / sương / bóng lấy từ cảnh chính, camera chính (đèn lọc theo lớp của nó). Nhóm làm nóng do car.ts dựng, không thêm vào scene */
47	drCarSetWarm(async (o: THREE.Object3D) => {
48	  const rt = renderer.getRenderTarget();
49	  renderer.setRenderTarget(null);
50	  const a = renderer.compileAsync(o, camera, scene);
51	  renderer.setRenderTarget(rt);
52	  await a;
53	  renderer.setRenderTarget(composer.readBuffer);
54	  const b = renderer.compileAsync(o, camera, scene);
55	  renderer.setRenderTarget(rt);
