73	/* Mạng đường dựng lần đầu vào chế độ, giữ lại cho các lần sau; cổng nhịp quay theo cầu hiện tại */
74	function drEnsureNet(): DrNet {
75	  if (!net) {
76	    const n = drMakeNet(drBuildPads(), drBuildSolids());
77	    drCollectRuntime(n, (scene.getObjectByName('tp-houses') as THREE.InstancedMesh) || null);   // một lần cho mỗi net (chỉ push)
