105	/* Xe đứng yên ở (x, z) hướng yaw, trạng thái mới từ drCreate (xóa trạng thái cọ tường); y bỏ trống thì lấy mặt đường cao nhất tại đó.
106	   Dùng cho test (__app.drive) và đặt lại vị trí */
107	function drPlaceAt(x: number, z: number, yaw: number, y?: number): void {
108	  if (!net) return;
109	  const s = drCreate(net, DR_SOLO_SLOT);
110	  let gy = -Infinity;
111	  for (const p of net.pads) {
112	    if (x < p.x0 || x > p.x1 || z < p.z0 || z > p.z1 || (p.gate !== undefined && net.closed.has(p.gate))) continue;
113	    gy = Math.max(gy, p.y(x, z));
114	  }
115	  s.x = x; s.z = z; s.yaw = yaw; s.y = y ?? (Number.isFinite(gy) ? gy : CONFIG.roadY);
116	  state = s;
117	  camS.yaw = 0; camS.pitch = 0; camS.idle = 0;
118	  drCars.place(DR_SELF, s);
119	  drCamPlace(camera, s, camS, net, 0, true);
120	  controls.target.set(s.x, s.y, s.z);
121	}
