123	export const drive = {
124	  active,
125	  get state(): DrState | null { return state; },
126	  get net(): DrNet | null { return net; },
127	  get cam(): DrCam { return camS; },
128	  /* Vào lái. solo: lái một mình (hiện luôn là một mình; slot nhiều người ở Task 11) */
129	  start(solo = true): void {
130	    const n = drEnsureNet();
131	    state = drCreate(n, DR_SOLO_SLOT);
132	    camS.yaw = 0; camS.pitch = 0; camS.idle = 0;
133	    drCars.sync([{ slot: DR_SELF }]);
134	    if (!drCars.group.parent) scene.add(drCars.group);
135	    drCars.place(DR_SELF, state);
136	    driveView.far = CONFIG.drive.tunnelFar;
137	    drKeys.clear(); touch?.reset();
138	    drHudShow(n); drSound.start();
139	    if (!saved) saved = { fov: camera.fov, explore: document.body.classList.contains('explore') };
140	    cam.flight.then = null; cam.mode = 'car'; controls.enabled = false;
141	    camera.fov = CONFIG.drive.cam.fov; onResize();   // onResize cập nhật ma trận chiếu và hệ số cỡ điểm theo fov mới
142	    drCamPlace(camera, state, camS, n, 0, true);
143	    controls.target.set(state.x, state.y, state.z);
144	    document.body.classList.add('explore', 'drive');
145	  },
146	  /* Chế độ xem bám xe người khác: Task 11. Hiện chưa có phiên lái nhiều người nên lái một mình */
147	  startWatching(): void { drive.start(true); },
148	  update(dt: number): void {
149	    if (!active()) return;
150	    drInputFromKeys(drKeys, _inp);
151	    if (touch) touch.read(_inp);   // gộp, không xóa phím
152	    drSound.horn(drKeys.has('KeyH'));
153	    advance(dt, _inp);
154	  },
155	  /* Gọi ngay sau lệnh vẽ khung chính (main.ts); chỗ cho HUD / chụp ảnh của task sau */
156	  afterRender(): void { /* chưa có việc */ },
157	  /* Rời chế độ: trả mọi thứ đã đổi (explore.exit tải lại trang ngay sau), kể cả khi cam.mode đã bị chỗ khác đổi khỏi 'car' */
158	  stop(): void {
159	    if (state === null) return;
160	    state = null; drKeys.clear(); touch?.reset();
161	    drHudHide(); drSound.stop();
162	    drCars.clear(); drCars.group.removeFromParent();
163	    driveView.far = 1;
164	    document.body.classList.remove('drive');
165	    if (saved) {
166	      if (!saved.explore) document.body.classList.remove('explore');
167	      camera.fov = saved.fov; onResize();                            // onResize tính lại ma trận chiếu và pScale theo fov cũ
168	      saved = null;
169	    }
170	    if (cam.mode === 'car') { cam.mode = 'orbit'; controls.enabled = true; }
171	  },
172	  /* Cho test: như update nhưng nhận đầu vào trực tiếp; đặt xe tại chỗ */
173	  step(dt: number, inp: DrInput): void { if (active()) advance(dt, inp); },
174	  placeAt: drPlaceAt,
175	  stats: drSceneStats,
176	  preload(): void { void drCarLoad(); }
177	};
