179	/* onExit: thoát chung (explore.exit); Task 11 dùng khi mất kết nối lúc đang xem, lái một mình chưa cần */
180	export function setupDrive(c: SwingController, onExit: () => void): void {
181	  ctrl = c;
182	  window.addEventListener('keydown', (e) => {
183	    if (!active() || e.key === 'Escape') return;   // Esc do explore/index.ts xử lý (thoát chung)
184	    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt không điều khiển xe, tránh kẹt phím
185	    if (isField(e.target)) return;                    // gõ trong ô nhập / chọn không điều khiển xe
186	    if (!DR_KEYS.has(e.code)) return;
187	    if (e.code.startsWith('Arrow') || e.code === 'Space') e.preventDefault();   // không cuộn trang, Space không bấm nút đang focus
188	    drKeys.add(e.code);
189	  });
190	  window.addEventListener('keyup', (e) => {
191	    drKeys.delete(e.code);
192	    if (e.code === 'Space' && active() && !isField(e.target)) e.preventDefault();
193	  });
194	  const drop = drBindDrop(window, document, drKeys);
195	  window.addEventListener('focusin', (e) => { if (active() && isField(e.target)) { drop(); touch?.reset(); drSound.horn(false); } });
196	  /* Tab ẩn hoặc mất tiêu điểm: vòng khung có thể dừng nên tắt còi ngay (phím đã nhả ở drBindDrop, cảm ứng tự reset trong touch.ts) */
197	  window.addEventListener('blur', () => drSound.horn(false));
198	  document.addEventListener('visibilitychange', () => { if (document.hidden) drSound.horn(false); });
199	  const hud = document.getElementById('drHud');
200	  if (hud) touch = drTouchBind(hud, {
201	    look: (dx, dy) => { if (active()) drCamDrag(camS, dx, dy); },
202	    activity: () => { /* Task 11: exMulti.activity() */ }
203	  });
204	  /* Kéo chuột trái trên canvas: xoay camera quanh xe (ngón tay vuốt #drLook trong touch.ts) */
205	  let dragId = -1, lx = 0, ly = 0;
206	  canvas.addEventListener('pointerdown', (e) => {
207	    if (!active() || e.pointerType === 'touch' || e.button !== 0) return;
208	    dragId = e.pointerId; lx = e.clientX; ly = e.clientY;
209	    canvas.setPointerCapture(e.pointerId);
210	  });
211	  canvas.addEventListener('pointermove', (e) => {
212	    if (e.pointerId !== dragId) return;
213	    drCamDrag(camS, e.clientX - lx, e.clientY - ly);
214	    lx = e.clientX; ly = e.clientY;
215	  });
216	  const end = (e: PointerEvent) => { if (e.pointerId === dragId) dragId = -1; };
217	  canvas.addEventListener('pointerup', end);
218	  canvas.addEventListener('pointercancel', end);
219	  canvas.addEventListener('lostpointercapture', end);
220	}
