1	/* ===== Lái xe: bộ quản lý xe của các người chơi (D-034) =====
2	   - drCars.group: gồm xe của từng slot (DrCar.group) và bánh dùng chung (drWheels.group); chưa có xe thì không có gì để vẽ.
3	   - sync(peers): tạo xe cho slot mới (màu theo multiParams.colors[slot]), gỡ xe của slot không còn. place / pos theo slot. */
4	import * as THREE from 'three';
5	import { multiParams } from '../multi/params';
6	import { DrCar, drCarDisposeShared, drWheels, type DrPlace } from './car';
7	
8	const cars = new Map<number, DrCar>();
9	const group = new THREE.Group();
10	group.name = 'drive-cars';
11	group.add(drWheels.group);
12	
13	export const drCars = {
14	  group,
15	  sync(peers: { slot: number }[]): void {
16	    const want = new Set<number>();
17	    for (const p of peers) {
18	      want.add(p.slot);
19	      if (cars.has(p.slot)) continue;
20	      const c = new DrCar(multiParams.colors[((p.slot % multiParams.colors.length) + multiParams.colors.length) % multiParams.colors.length]);
21	      cars.set(p.slot, c); group.add(c.group);
22	    }
23	    for (const [s, c] of cars) if (!want.has(s)) { c.dispose(); cars.delete(s); }
24	  },
25	  place(slot: number, p: DrPlace): void { cars.get(slot)?.place(p); },
26	  /* Vị trí xe của slot vào out; false nếu không có xe */
27	  pos(slot: number, out: THREE.Vector3): boolean {
28	    const c = cars.get(slot);
29	    if (!c) return false;
30	    out.copy(c.group.position);
31	    return true;
32	  },
33	  clear(): void { for (const c of cars.values()) c.dispose(); cars.clear(); },
34	  /* Gỡ hết, kể cả vật liệu / bánh dùng chung (rời chế độ hẳn) */
35	  dispose(): void { this.clear(); drCarDisposeShared(); }
36	};
