1	/* ===== Dù lượn nhiều người: định dạng tin khách ⇄ máy chủ (JSON) ===== */
2	import { multiParams } from './params';
3	
4	export type ClientMsg =
5	  | { t: 'join'; name: string; kind?: 'walk' | 'drive' }   // kind: 'walk' = xin chỗ đi dạo, 'drive' = chỗ lái xe; không có = chỗ bay (khách cũ)
6	  | { t: 'pos'; x: number; y: number; z: number; yaw: number; bank: number; ts?: number }   // ts: giờ gửi theo đồng hồ của khách (ms); máy chủ cũ bỏ qua
7	  | { t: 'pos'; x: number; y: number; z: number; yaw: number; pose: number; ts?: number }   // người đi dạo: pose (0 đứng, 1 đi, 2 chạy, 3 rơi (bản cũ: nhảy), 4 chụp ảnh), không có bank
8	  | { t: 'pos'; x: number; y: number; z: number; yaw: number; v: number; st: number; ts?: number }   // người lái: v tốc độ có dấu (m/s), st góc lái (rad); không có bank / pose
9	  | { t: 'hb' }
10	  | { t: 'leave' };
11	
12	export interface Flyer { slot: number; name: string }
13	
14	export type Kind = 'fly' | 'walk' | 'drive';
15	
16	// f: mỗi phần tử [slot, x, y, z, yaw, bank, giờ gửi (ms)]; chỉ gồm slot có vị trí mới. Giờ gửi = ts của khách, khách cũ không gửi ts thì là giờ máy chủ nhận;
17	// mỗi slot một trục giờ riêng, khách nhận tự quy đổi. Máy chủ cũ (trước bản sửa giật) gửi 6 phần tử và phát lại vị trí cũ của mọi slot: khách mới nhận được cả hai dạng.
18	// Đi dạo: lobby thêm walkers (flyers chỉ có người bay), pos thêm w (mỗi phần tử [slot, x, y, z, yaw, pose, giờ gửi]; f luôn có, có thể rỗng); khách cũ bỏ qua trường lạ
19	// Lái xe: lobby thêm drivers, pos thêm d (mỗi phần tử [slot, x, y, z, yaw, v, st, giờ gửi]); máy chủ cũ không gửi drivers, khách mới thấy vậy thì lái một mình
20	export type ServerMsg =
21	  | { t: 'lobby'; flyers: Flyer[]; walkers?: Flyer[]; drivers?: Flyer[] }
22	  | { t: 'joined'; slot: number; kind?: 'walk' | 'drive' }
23	  | { t: 'rejected'; why: 'full' | 'name'; kind?: 'walk' | 'drive' }
24	  | { t: 'pos'; f: number[][]; w?: number[][]; d?: number[][] }   // d: [slot, x, y, z, yaw, v, st, giờ gửi]
25	  | { t: 'released' };
26	
27	// Ký tự trông như khoảng trống dù thuộc nhóm chữ/ký hiệu (chữ đệm Hangul, chữ nổi trống, nguyên âm ẩn Khmer): không tính là chữ thấy được
28	const BLANK = /[\u115F\u1160\u3164\uFFA0\u2800\u17B4\u17B5]/gu;
29	const VISIBLE = /[\p{L}\p{N}\p{S}\p{P}]/u;
30	
31	/* Bỏ ký tự điều khiển và bidi/định dạng (giữ U+200D để ghép emoji), cắt khoảng trắng.
32	   null nếu: rỗng; không có chữ/số/ký hiệu/dấu câu nào thấy được; quá nameMax grapheme; một grapheme quá graphemeCpMax code point (chồng dấu); tổng quá nameCpMax code point */
33	export function exSanitizeName(raw: string): string | null {
34	  if (typeof raw !== 'string') return null;
35	  const s = raw.replace(/[\p{Cc}\p{Cf}]/gu, c => (c === '\u200D' ? c : '')).trim();
36	  if (!s || !VISIBLE.test(s.replace(BLANK, ''))) return null;
37	  const seg = new Intl.Segmenter(undefined, { granularity: 'grapheme' });
38	  let n = 0, cps = 0;
39	  for (const g of seg.segment(s)) {
40	    let k = 0;
41	    for (const _ of g.segment) k++;
42	    cps += k;
43	    if (++n > multiParams.nameMax || k > multiParams.graphemeCpMax || cps > multiParams.nameCpMax) return null;
44	  }
45	  return s;
46	}
47

