1	/* ===== Dù lượn nhiều người: nội suy vị trí dù người khác (thuần, không import) =====
2	   Vòng đệm cố định 8 mẫu (t, x, y, z, yaw, bank), nội suy tuyến tính, yaw đi đường ngắn qua ±π, kẹp ở mẫu cuối. Không cấp phát khi push/sample (D-018).
3	   Mẫu đặt theo giờ của người gửi (e[6]) quy ra giờ khách, nên trễ mạng và việc máy chủ gộp gói không làm dù đứng rồi vọt. */
4	const N = 8, W = 6;   // số mẫu tối đa; số trường mỗi mẫu
5	export interface ExPose { x: number; y: number; z: number; yaw: number; bank: number }
6	export interface ExClockParams { clockRelax: number; clockSlewMs: number; clockWarmup: number }   // xem multiParams
7	
8	export class ExTrack {
9	  private buf = new Float64Array(N * W);
10	  private head = 0;      // chỉ số ô sẽ ghi tiếp
11	  private n = 0;         // số mẫu đang có
12	  private off = NaN;     // độ lệch giờ người gửi → giờ khách (ms); NaN = chưa có mẫu nào có giờ
13	  private fed = 0;       // số mẫu có giờ đã nhận: clockWarmup mẫu đầu lấy thẳng mức nhỏ nhất (gói đầu có thể trễ vì khung hình chậm), sau đó mới giới hạn slew
14	  get count(): number { return this.n; }
15	
16	  push(t: number, x: number, y: number, z: number, yaw: number, bank: number): void {
17	    if (this.n > 0 && t <= this.buf[((this.head + N - 1) % N) * W]) return;   // mẫu cũ hoặc trùng giờ: bỏ để giữ thứ tự
18	    const o = this.head * W, b = this.buf;
19	    b[o] = t; b[o + 1] = x; b[o + 2] = y; b[o + 3] = z; b[o + 4] = yaw; b[o + 5] = bank;
20	    this.head = (this.head + 1) % N;
21	    if (this.n < N) this.n++;
22	  }
23	
24	  /* Một mục của gói pos e = [slot, x, y, z, yaw, bank, giờ gửi?] nhận lúc nowMs.
25	     Có giờ gửi (máy chủ mới): giờ khách = giờ gửi + độ lệch; độ lệch bám mức nhỏ nhất (gói ít trễ nhất) nhưng sau clockWarmup mẫu đầu mỗi mẫu chỉ giảm tối đa clockSlewMs,
26	     và nới lên clockRelax phần chênh khi mạng chậm đi: độ lệch đổi chậm nên dù không bị co giãn thời gian.
27	     Không có (máy chủ cũ phát lại vị trí cũ của mọi slot mỗi gói): đóng dấu giờ nhận, bỏ mục trùng mẫu cuối để dù không đứng chờ */
28	  feed(e: number[], nowMs: number, k: ExClockParams): void {
29	    const ts = e[6];
30	    if (typeof ts === 'number' && Number.isFinite(ts)) {
31	      const c = nowMs - ts;
32	      if (this.off !== this.off || (c < this.off && this.fed < k.clockWarmup)) this.off = c;
33	      else if (c < this.off) this.off -= Math.min(this.off - c, k.clockSlewMs);
34	      else this.off += (c - this.off) * k.clockRelax;
35	      this.fed++;
36	      this.push(ts + this.off, e[1], e[2], e[3], e[4], e[5]);
37	      return;
38	    }
39	    if (this.n > 0) {
40	      const o = ((this.head + N - 1) % N) * W, b = this.buf;
41	      if (b[o + 1] === e[1] && b[o + 2] === e[2] && b[o + 3] === e[3] && b[o + 4] === e[4] && b[o + 5] === e[5]) return;
42	    }
43	    this.push(nowMs, e[1], e[2], e[3], e[4], e[5]);
44	  }
45	
46	  /* Ghi vị trí tại thời điểm t vào out; false nếu chưa có mẫu.
47	     step = true: trường thứ 6 (bank; người đi dạo dùng chở pose) không nội suy, lấy nguyên của mẫu trước, tới đúng giờ mẫu sau mới đổi */
48	  sample(t: number, out: ExPose, step = false): boolean {
49	    if (this.n === 0) return false;
50	    const b = this.buf, first = (this.head + N - this.n) % N * W;
51	    const last = ((this.head + N - 1) % N) * W;
52	    let a = first, c = first;
53	    if (t >= b[last]) a = c = last;
54	    else if (t > b[first]) {
55	      for (let i = 0; i < this.n - 1; i++) {
56	        const p = (first + i * W) % (N * W), q = (p + W) % (N * W);
57	        if (t <= b[q]) { a = p; c = q; break; }
58	      }
59	    }
60	    const k = a === c ? 0 : (t - b[a]) / (b[c] - b[a]);
61	    out.x = b[a + 1] + (b[c + 1] - b[a + 1]) * k;
62	    out.y = b[a + 2] + (b[c + 2] - b[a + 2]) * k;
63	    out.z = b[a + 3] + (b[c + 3] - b[a + 3]) * k;
64	    let dy = b[c + 4] - b[a + 4];
65	    dy -= Math.round(dy / (2 * Math.PI)) * 2 * Math.PI;
66	    out.yaw = b[a + 4] + dy * k;
67	    out.bank = step ? b[(k >= 1 ? c : a) + 5] : b[a + 5] + (b[c + 5] - b[a + 5]) * k;
68	    return true;
69	  }
70	
71	  reset(): void { this.n = 0; this.head = 0; this.off = NaN; this.fed = 0; }
72	}
73

1	/* ===== Dù lượn nhiều người: định dạng tin khách ⇄ máy chủ (JSON) ===== */
2	import { multiParams } from './params';
3	
4	export type ClientMsg =
5	  | { t: 'join'; name: string; kind?: 'walk' | 'drive' }   // kind: 'walk' = xin chỗ đi dạo, 'drive' = chỗ lái xe; không có = chỗ bay (khách cũ)
6	  | { t: 'pos'; x: number; y: number; z: number; yaw: number; bank: number; ts?: number }   // ts: giờ gửi theo đồng hồ của khách (ms); máy chủ cũ bỏ qua
7	  | { t: 'pos'; x: number; y: number; z: number; yaw: number; pose: number; ts?: number }   // người đi dạo: pose (0 đứng, 1 đi, 2 chạy, 3 rơi (bản cũ: nhảy), 4 chụp ảnh), không có bank
8	  | { t: 'pos'; x: number; y: number; z: number; yaw: number; v: number; st: number; ts?: number }   // người lái: v tốc độ có dấu (m/s), st góc lái (rad); không có bank / pose
9	  | { t: 'hb' }
10	  | { t: 'leave' };
11	
12	export interface Flyer { slot: number; name: string }
13	
14	export type Kind = 'fly' | 'walk' | 'drive';
15	
16	// f: mỗi phần tử [slot, x, y, z, yaw, bank, giờ gửi (ms)]; chỉ gồm slot có vị trí mới. Giờ gửi = ts của khách, khách cũ không gửi ts thì là giờ máy chủ nhận;
17	// mỗi slot một trục giờ riêng, khách nhận tự quy đổi. Máy chủ cũ (trước bản sửa giật) gửi 6 phần tử và phát lại vị trí cũ của mọi slot: khách mới nhận được cả hai dạng.
18	// Đi dạo: lobby thêm walkers (flyers chỉ có người bay), pos thêm w (mỗi phần tử [slot, x, y, z, yaw, pose, giờ gửi]; f luôn có, có thể rỗng); khách cũ bỏ qua trường lạ
19	// Lái xe: lobby thêm drivers, pos thêm d (mỗi phần tử [slot, x, y, z, yaw, v, st, giờ gửi]); máy chủ cũ không gửi drivers, khách mới thấy vậy thì lái một mình
20	export type ServerMsg =
21	  | { t: 'lobby'; flyers: Flyer[]; walkers?: Flyer[]; drivers?: Flyer[] }
22	  | { t: 'joined'; slot: number; kind?: 'walk' | 'drive' }
23	  | { t: 'rejected'; why: 'full' | 'name'; kind?: 'walk' | 'drive' }
24	  | { t: 'pos'; f: number[][]; w?: number[][]; d?: number[][] }   // d: [slot, x, y, z, yaw, v, st, giờ gửi]
25	  | { t: 'released' };
26	
27	// Ký tự trông như khoảng trống dù thuộc nhóm chữ/ký hiệu (chữ đệm Hangul, chữ nổi trống, nguyên âm ẩn Khmer): không tính là chữ thấy được
28	const BLANK = /[\u115F\u1160\u3164\uFFA0\u2800\u17B4\u17B5]/gu;
29	const VISIBLE = /[\p{L}\p{N}\p{S}\p{P}]/u;
30	
31	/* Bỏ ký tự điều khiển và bidi/định dạng (giữ U+200D để ghép emoji), cắt khoảng trắng.
32	   null nếu: rỗng; không có chữ/số/ký hiệu/dấu câu nào thấy được; quá nameMax grapheme; một grapheme quá graphemeCpMax code point (chồng dấu); tổng quá nameCpMax code point */
33	export function exSanitizeName(raw: string): string | null {
34	  if (typeof raw !== 'string') return null;
35	  const s = raw.replace(/[\p{Cc}\p{Cf}]/gu, c => (c === '\u200D' ? c : '')).trim();
36	  if (!s || !VISIBLE.test(s.replace(BLANK, ''))) return null;
37	  const seg = new Intl.Segmenter(undefined, { granularity: 'grapheme' });
38	  let n = 0, cps = 0;
39	  for (const g of seg.segment(s)) {
40	    let k = 0;
41	    for (const _ of g.segment) k++;
42	    cps += k;
43	    if (++n > multiParams.nameMax || k > multiParams.graphemeCpMax || cps > multiParams.nameCpMax) return null;
44	  }
45	  return s;
46	}
