259	/* ===== Một xe ===== */
260	export class DrCar {
261	  readonly group = new THREE.Group();
262	  private readonly color: string;
263	  private temp: THREE.Mesh | null;
264	  private tempGeo: THREE.BufferGeometry | null;
265	  private shadow: THREE.Mesh;
266	  private body: THREE.Object3D | null = null;
267	  private paint: THREE.MeshStandardMaterial | null = null;
268	  private tailMeshes: THREE.Mesh[] = [];
269	  private src: DrSource | null = null;
270	  private slot = -1;
271	  private disposed = false;
272	  private brakingNow = false;
273	  private last: DrPlace | null = null;
274	
275	  constructor(color: string) {
276	    this.color = color;
277	    this.group.name = 'drive-car';
278	    this.group.matrixAutoUpdate = true;
279	    this.tempGeo = drTempGeometry(color);
280	    this.temp = new THREE.Mesh(this.tempGeo, drTempMaterial());
281	    this.temp.layers.set(1); this.temp.castShadow = false; this.temp.receiveShadow = false;
282	    this.group.add(this.temp);
283	    drShadowShared();
284	    this.shadow = new THREE.Mesh(shadowGeo!, shadowMat!);
285	    this.shadow.scale.set(CAR.length + 2 * M.shadow.pad, 1, CAR.width + 2 * M.shadow.pad);
286	    this.shadow.position.y = M.shadow.lift;
287	    this.shadow.layers.set(1); this.shadow.castShadow = false; this.shadow.receiveShadow = false; this.shadow.renderOrder = 1;
288	    this.group.add(this.shadow);
289	    void drCarLoad();
290	    late!.then((scene) => { const src = scene && sources.get(scene); if (src && !this.disposed) this.swap(src); });   // không bao giờ từ chối; nguồn của bộ nạp cũ (test đổi bộ nạp) thì bỏ
291	  }
292	
293	  get real(): boolean { return this.body !== null; }
294	
295	  /* Đổi hình tạm sang bản sao mô hình thật, giữ nguyên vị trí */
296	  private swap(src: DrSource): void {
297	    if (this.body) return;
298	    drWheels.setup(src);
299	    this.slot = drWheels.acquire();
300	    this.src = src;
301	    const body = src.body.clone();
302	    this.paint = src.paint.clone();
303	    this.paint.color.set(this.color); this.paint.roughness = M.paintRough; this.paint.metalness = M.paintMetal;
304	    body.traverse((o) => {
305	      const m = o as THREE.Mesh;
306	      if (!m.isMesh) return;
307	      const mat = m.material as THREE.Material;
308	      if (mat.name === 'paint') m.material = this.paint!;
309	      else if (mat === src.tail) this.tailMeshes.push(m);
310	    });
311	    this.body = body;
312	    this.group.add(body);
313	    if (this.temp) { this.group.remove(this.temp); this.temp = null; this.tempGeo!.dispose(); this.tempGeo = null; }
314	    this.brakingNow = false;
315	    if (this.last) this.place(this.last);
316	  }
317	
318	  place(p: DrPlace): void {
319	    const l = this.last || (this.last = { x: 0, y: 0, z: 0, yaw: 0, pitch: 0, steer: 0, wheel: 0, braking: false });
320	    l.x = p.x; l.y = p.y; l.z = p.z; l.yaw = p.yaw; l.pitch = p.pitch; l.steer = p.steer; l.wheel = p.wheel; l.braking = p.braking;
321	    const g = this.group;
322	    g.position.set(p.x, p.y, p.z);
323	    g.quaternion.setFromAxisAngle(AXY, p.yaw).multiply(B3.setFromAxisAngle(AXZ, p.pitch));
324	    if (!this.body) return;
325	    if (p.braking !== this.brakingNow) {
326	      this.brakingNow = p.braking;
327	      const mat = p.braking ? this.src!.tailBrake : this.src!.tail;
328	      for (const m of this.tailMeshes) m.material = mat;
329	    }
330	    if (this.slot >= 0) { g.updateMatrix(); drWheels.set(this.slot, g.matrix, p.steer, p.wheel); }
331	  }
332	
333	  dispose(): void {
334	    if (this.disposed) return;
335	    this.disposed = true;
336	    this.group.removeFromParent();
337	    drWheels.release(this.slot); this.slot = -1;
338	    this.tempGeo?.dispose(); this.tempGeo = null;
339	    this.paint?.dispose(); this.paint = null;
340	    this.body = null; this.temp = null; this.tailMeshes.length = 0;
341	  }
342	}
