content.content:
.ex-mp-btn.ex-mp-alt:hover:not(:disabled){background:rgba(255,255,255,.08);}
/* Khi bay: chỉ còn ngôn ngữ, Ngày/Đêm, Chất lượng hình, dòng hướng dẫn và nút Thoát; mọi nút góc nhìn / cầu / Tour ẩn để không thoát chế độ bay bằng đường khác */
#exHint,#exSpeed,#btnExExit,#exMpLabels,#exMpRoster,#exMpNotice{display:none;}
body.explore #exSpeed{display:block;position:fixed;left:50%;transform:translateX(-50%);bottom:calc(14px + env(safe-area-inset-bottom,0px));padding:6px 14px;font-size:13px;color:var(--text);direction:ltr;font-variant-numeric:tabular-nums;white-space:nowrap;pointer-events:none;}
body.explore #exHint{display:block;position:fixed;left:50%;transform:translateX(-50%);top:calc(14px + env(safe-area-inset-top,0px));padding:8px 14px;font-size:12px;color:var(--text);text-align:center;max-width:calc(100vw - 32px);box-sizing:border-box;}
body.explore #btnExExit{display:block;inset-inline-end:calc(14px + env(safe-area-inset-right,0px));top:calc(56px + env(safe-area-inset-top,0px));padding:8px 14px;font-size:12px;color:var(--text);cursor:pointer;}
body.explore #exMpLabels{display:block;position:fixed;inset:0;pointer-events:none;overflow:hidden;z-index:5;}
.ex-mp-label{position:absolute;left:0;top:0;padding:2px 7px;font:500 11px/1.2 var(--font-body);color:var(--text);background:rgba(10,18,30,.72);border-radius:4px;white-space:nowrap;will-change:transform;direction:ltr;}
.ex-mp-label[hidden]{display:none;}
body.explore #exMpRoster:not([hidden]){display:flex;flex-direction:column;gap:3px;position:fixed;inset-inline-end:calc(14px + env(safe-area-inset-right,0px));bottom:calc(14px + env(safe-area-inset-bottom,0px));padding:8px 12px;font-size:12px;color:var(--text);pointer-events:none;z-index:5;}
.ex-mp-head{font-weight:600;margin-bottom:2px;}
.ex-mp-row{display:flex;align-items:center;gap:6px;}
.ex-mp-row.me{font-weight:600;}
.ex-mp-row i{width:9px;height:9px;border-radius:50%;flex:none;}
.ex-mp-row.walk i{border-radius:2px;}   /* người đi dạo: chấm vuông, người bay: chấm tròn */
body.explore #exMpNotice:not([hidden]){display:block;position:fixed;left:50%;transform:translateX(-50%);top:calc(100px + env(safe-area-inset-top,0px));padding:8px 14px;font-size:12px;color:var(--text);z-index:5;}
/* Chế độ xem (hết chỗ hoặc vừa nhường chỗ): không có dù của mình nên ẩn dòng hướng dẫn lái và đồng hồ; hiện "Đang xem" và lời mời */
body.ex-watching #exHint,body.ex-watching #exSpeed{display:none;}
/* Lái xe (explore/drive): chữ và tốc độ của dù lượn ẩn; #drHud là khung HUD riêng (hud.ts, touch.ts): đồng hồ, bản đồ nhỏ, gợi ý phím, cần gạt + bàn đạp cảm ứng.
   Lớp phủ trong suốt, chỉ các điều khiển nhận chạm; direction:ltr (dir="ltr" trên #drHud) để ar (RTL) vẫn giữ cần gạt bên trái, bàn đạp bên phải, không lật. */
body.explore.drive #exHint,body.explore.drive #exSpeed{display:none;}
#drHud,#drLook,#drSteer,#drGas,#drBrake{display:none;}
body.drive #drHud{display:block;position:fixed;inset:0;z-index:4;pointer-events:none;touch-action:none;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none;}
#drMap,#drMapNote,#drSpeed,#drHint{position:fixed;pointer-events:none;}
#drMap{display:block;left:calc(14px + env(safe-area-inset-left,0px));bottom:calc(44px + env(safe-area-inset-bottom,0px));background:var(--panel);border:1px solid var(--panel-line);border-radius:6px;}   /* bản đồ nhỏ: dưới trái; Bắc ở trên */
#drMapNote{left:calc(14px + env(safe-area-inset-left,0px));bottom:calc(14px + env(safe-area-inset-bottom,0px));padding:5px 9px 5px 22px;font-size:11px;line-height:1.2;color:var(--text);max-width:260px;box-sizing:border-box;}
#drMapNote::before{content:"";position:absolute;left:8px;top:50%;width:9px;height:9px;margin-top:-4.5px;border-radius:50%;background:#e08a3c;}   /* cùng màu ô hầm trên bản đồ (CONFIG.drive.hud.colors.tunnel) */
#drSpeed{right:calc(14px + env(safe-area-inset-right,0px));bottom:calc(14px + env(safe-area-inset-bottom,0px));padding:6px 14px;display:flex;align-items:baseline;gap:6px;color:var(--text);}   /* đồng hồ: dưới phải */
#drKmh{font:700 34px/1 var(--font-display);color:var(--gold);min-width:3ch;text-align:right;font-variant-numeric:tabular-nums;}
#drSpeedUnit{font-size:12px;}
#drHint{display:none;}
#drHint.off{opacity:0;transition:opacity .6s;}
@media (hover:hover){
  body.drive #drHint{display:block;left:50%;transform:translateX(-50%);top:calc(14px + env(safe-area-inset-top,0px));padding:8px 14px;font-size:12px;color:var(--text);text-align:center;max-width:calc(100vw - 200px);box-sizing:border-box;}
}
body.drive #scene{cursor:grab;}
body.drive #scene:active{cursor:grabbing;}
