function braking(g: THREE.Object3D): boolean {
  let b = false;
  g.traverse((o) => { const m = o as THREE.Mesh; if (m.isMesh && m.material && ((m.material as THREE.Material).userData.lampBrake ?? 0) > 1) b = true; });
  return b;
}

