function pk(slot: number, v: number, t0: number, n: number, y = 2.6, st = 0): number[][] {
  return Array.from({ length: n }, (_, k) => { const ts = t0 + k * 1000 / P.sendHz; return [slot, 100 + v * ts / 1000, y, 5, 0, v, st, ts]; });
}

