/* Kịch bản tay (không phải bộ test): hai trang Chromium cùng vào lái qua wrangler dev cục bộ; chụp sảnh, góc nhìn của máy A thấy xe + tên máy B, danh sách. */
import { spawn } from 'node:child_process';
import fs from 'node:fs';
const REPO = 'D:/2026 - Tuan/danang-vite';
const { serveDir, launch, openApp, frames } = await import('file:///' + REPO + '/tests/lib.mjs');
const PORT = 8799, HOST = `127.0.0.1:${PORT}`;
const OUT = REPO + '/tests/screens/';
fs.mkdirSync(OUT, { recursive: true });
const wr = spawn('npx.cmd', ['wrangler', 'dev', '--port', String(PORT)], { cwd: REPO + '/server/multi', shell: true, stdio: ['ignore', 'pipe', 'pipe'] });
let log = ''; wr.stdout.on('data', (d) => { log += d; }); wr.stderr.on('data', (d) => { log += d; });
const stop = () => { try { spawn('taskkill', ['/pid', String(wr.pid), '/T', '/F']); } catch { /* bỏ qua */ } };
process.on('exit', stop);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const t0 = Date.now(), lap = (m) => console.log(`[${Math.round((Date.now() - t0) / 1000)}s] ${m}`);
let srv, browser;
try {
  for (let i = 0; i < 120; i++) { if (/Ready on/.test(log)) break; await sleep(500); }
  lap('wrangler: ' + (/Ready on/.test(log) ? 'sẵn sàng' : 'KHÔNG sẵn sàng'));
  srv = await serveDir(REPO + '/dist/');
  browser = await launch();
  const URL = srv.url + '?chooser&idleMs=600000&multi=' + encodeURIComponent(`ws://${HOST}/sky`);
  const join = async (P, name, shot) => {
    const page = P.page; page.setDefaultTimeout(240000);
    await page.waitForFunction(() => !document.getElementById('chooser').hidden);
    await page.click('[data-pick="car"]');
    await page.waitForFunction(() => window.__app.multi.session && window.__app.multi.session.phase === 'lobby');
    await page.fill('#exMpNameIn', name);
    await frames(page, 2);
    if (shot) await page.screenshot({ path: OUT + shot });
    await page.click('#exMpFly');
    await page.waitForFunction(() => window.__app.drive.state && window.__app.multi.session.phase === 'flying');
  };
  const A = await openApp(browser, URL, { width: 1280, height: 720 });
  lap('A mở'); await join(A, 'Minh', null); lap('A đang lái, slot ' + await A.page.evaluate(() => window.__app.multi.session.mySlot));
  const B = await openApp(browser, URL, { width: 1280, height: 720 });
  lap('B mở'); await join(B, 'Lan', 'drive-multi-lobby.png'); lap('B đang lái, slot ' + await B.page.evaluate(() => window.__app.multi.session.mySlot));
  await A.page.waitForFunction(() => [...document.querySelectorAll('#exMpLabels .ex-mp-label')].some((e) => !e.hidden && e.textContent.includes('Lan')), null, { polling: 2000, timeout: 300000 });
  lap('A thấy nhãn "Lan"');
  await frames(A.page, 2);
  const info = await A.page.evaluate(() => ({
    roster: document.getElementById('exMpRoster').innerText, labels: [...document.querySelectorAll('#exMpLabels .ex-mp-label')].filter((e) => !e.hidden).map((e) => e.textContent),
    cls: document.body.className, kind: window.__app.multi.session.kind, slot: window.__app.multi.session.mySlot,
    drivers: window.__app.multi.session.drivers.map((d) => d.slot + ':' + d.name),
    rosterBox: JSON.stringify(document.getElementById('exMpRoster').getBoundingClientRect()), speedBox: JSON.stringify(document.getElementById('drSpeed').getBoundingClientRect()),
    statsBox: JSON.stringify(document.querySelector('.stats').getBoundingClientRect()), exitBox: JSON.stringify(document.getElementById('btnExExit').getBoundingClientRect())
  }));
  console.log(JSON.stringify(info, null, 1));
  await A.page.screenshot({ path: OUT + 'drive-multi-A.png' });
  const rb = JSON.parse(info.rosterBox);
  await A.page.screenshot({ path: OUT + 'drive-multi-roster.png', clip: { x: Math.max(0, rb.left - 10), y: Math.max(0, rb.top - 10), width: Math.min(1280, rb.width + 20), height: rb.height + 20 } });
  lap('đã chụp');
  console.log('lỗi A:', A.errors.length, A.errors.slice(0, 3)); console.log('lỗi B:', B.errors.length, B.errors.slice(0, 3));
} catch (e) { console.log('NGOẠI LỆ', e); }
finally { try { await browser?.close(); } catch { /* bỏ qua */ } srv?.close(); stop(); lap('xong'); setTimeout(() => process.exit(0), 1500); }

